const stories = [
  story("st_eidsvolls_plass_navnet_1864", "Et Eidsvoll i hovedstadens gatebilde", "historical_event", 1864, "Navnet bandt den nye stortingsbygningen til minnet om riksforsamlingen i 1814.", "Staten overtok Huseiertomten i 1858 med en bestemmelse som holdt området ubebygd. Samtidig var Stortingets nye bygning under oppføring i nærheten.\n\nI 1864 fikk parken navnet Eidsvolls plass. Navnet hentet riksforsamlingen i 1814 inn i hovedstadens daglige gatebilde.\n\nPlassen ble dermed et minnepolitisk rom før den ble en moderne demonstrasjonsarena. Navnet minner om en historisk forsamling, mens dagens Storting ligger fysisk ved siden av.", ["staten", "Kristiania kommune"], "Området fikk navnet Eidsvolls plass.", "1814-minnet ble festet til byrommet ved Stortinget.", [], ["1864", "stedsnavn", "1814"], ["oslo_history", "storting_place"], 2, 15),
  story("st_eidsvolls_plass_wergeland_1881", "Bok, penn og folkefest", "historical_event", 1881, "Wergelandmonumentet ble avduket 17. mai og gjorde dikteren til offentlig minne på plassen.", "Brynjulf Bergslien fikk oppdraget med et monument over Henrik Wergeland. Figuren ble formet med bok i venstre hånd og penn i høyre.\n\n17. mai 1881 ble monumentet avduket på Eidsvolls plass. Bjørnstjerne Bjørnson holdt tale mens en stor folkemengde samlet seg rundt statuen.\n\nMonumentet ga plassen et nytt fast midtpunkt for 17. mai, taler og minnekultur. Samtidig viser avdukingen hvordan offentligheten både skapes av fysiske verk og handlingene rundt dem.", ["Brynjulf Bergslien", "Bjørnstjerne Bjørnson"], "Wergelandmonumentet ble avduket.", "Dikteren fikk et varig offentlig minne på plassen.", [personId, "henrik_wergeland", "bjornstjerne_bjornson"], ["1881", "monument", "17_mai"], ["oslo_statue", "nkl_bergslien"]),
  story("st_eidsvolls_plass_vietnam_1968", "Verdenskrigen som fylte plassen", "historical_event", 1968, "Vietnamdemonstrasjonen viste hvordan internasjonal konflikt ble del av norsk offentlighet ved Stortinget.", "På 1960-tallet ble Eidsvolls plass tatt i bruk av stadig flere politiske bevegelser. Krigen i Vietnam mobiliserte unge, organisasjoner og partier langt utenfor Norge.\n\nI 1968 samlet en stor Vietnamdemonstrasjon seg på plassen foran Stortinget. Nærheten til nasjonalforsamlingen gjorde protesten synlig, men folkemengden var ikke selv et formelt vedtaksorgan.\n\nHendelsen viser hvordan en global konflikt kunne få en konkret norsk adresse. For å vurdere politisk virkning må demonstrasjonen kobles til debatt, dokumenter og senere beslutninger.", ["Vietnambevegelsen", "demonstranter"], "En stor demonstrasjon mot Vietnamkrigen brukte plassen.", "Eidsvolls plass ble tydeligere etablert som arena for utenrikspolitisk protest.", [], ["1968", "vietnam", "internasjonal_solidaritet"], ["storting_place", "oslo_vietnam_photo"], 3, 20),
  story("st_eidsvolls_plass_alta_sultestreik_1979", "Lavvoen som flyttet Alta-saken til Oslo", "turning_point", 1979, "Samiske aktivister gjorde Alta-konflikten synlig ved Stortinget gjennom sultestreik og lavvo.", "Høsten 1979 reiste samiske aktivister en lavvo på Eidsvolls plass og begynte sultestreik mot utbyggingen av Alta-Kautokeino-vassdraget. Konflikten fra nord ble flyttet til landets mest synlige politiske plass.\n\nAksjonen skapte uro og oppmerksomhet. Regjeringen stanset anleggsarbeidet midlertidig og varslet ny behandling, men utbyggingen ble senere vedtatt og gjennomført etter videre konflikt.\n\nAlta-saken fikk stor betydning for oppmerksomheten om samiske rettigheter og bidro til en lengre institusjonell utvikling. Historien viser både kraften i offentlig protest og grensen mellom mobilisering, regjeringsrespons og formelt vedtak.", ["samiske aktivister", "regjeringen", "Stortinget"], "Samiske aktivister sultestreiket mot Alta-utbyggingen.", "Saken fikk midlertidig stans, ny behandling og langsiktig betydning for samiske rettigheter.", [], ["1979", "alta", "samiske_rettigheter", "sultestreik"], ["storting_protest", "storting_alta"], 4, 17)
];
